# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.55.0/ankra-cli-darwin-arm64"
      sha256 "0deb5ab19d7165ce87fac64d7b16825ea18d622299cfbc37ee8b6bf0f2dbfcd8"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.55.0/ankra-cli-darwin-amd64"
      sha256 "d7583cd8109c89ac816b7544218c9bff823436a9794d48c0a7be63455ce0489f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.55.0/ankra-cli-linux-arm64"
      sha256 "04ca25258ea3f5fa6cd7cce0edc7e1cca3b4581033e876bfa0184e701ec9566f"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.55.0/ankra-cli-linux-amd64"
